return [{json:{...input,stateRpcBody:{p_outbox_id:input.outbox_id||input.outboxId,p_lease_token:input.lease_token||input.leaseToken,p_expected_outbox_version:Number(input.outbox_version??input.outboxVersion),p_receipt_json:input.stateQdrantReceipt}}}];

