return rows.filter(row=>row&&row.delivery_id&&row.lease_token).map(row=>({json:{...row,stateDelivery:row}}));

'use strict';
const row=$input.first()?.json||{};
const chatId=String(row.telegram_chat_id||row.telegramChatId||row.delivery_address||row.deliveryAddress||'').trim();
const content=String(row.content_text||row.contentText||'').trim();
return [{json:{...row,stateDelivery:row.stateDelivery||row,telegramRequestBody:{chat_id:chatId,text:content},stateDeliveryReady:Boolean(chatId&&content),stateDeliveryError:chatId&&content?'':'delivery_context_missing'}}];

'use strict';
const source=$('Code | Build State Delivery Telegram Request | Delivery').item.json||{};
const response=$input.first()?.json||{};
const externalId=String(response.message_id||response.result?.message_id||'').trim();
const zone=String(source.timezone||'Asia/Novosibirsk');
const parts=new Intl.DateTimeFormat('en-CA',{timeZone:zone,year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());
const part=type=>parts.find(value=>value.type===type)?.value||'';
const sentOn=`${part('year')}-${part('month')}-${part('day')}`;
return [{json:{...source,stateDeliverySendConfirmed:Boolean(externalId),stateDeliveryExternalMessageId:externalId,stateRpcBody:{p_delivery_id:source.delivery_id||source.deliveryId,p_lease_token:source.lease_token||source.leaseToken,p_expected_delivery_version:Number(source.delivery_version??source.deliveryVersion),p_confirmation_key:`delivery_confirm:${source.delivery_id||source.deliveryId}`,p_external_message_id:externalId,p_sent_at:new Date().toISOString(),p_sent_on:sentOn,p_evaluation_delay_days:null}}}];

