return [{json:{...source,stateRpcBody:{p_delivery_id:source.delivery_id||source.deliveryId,p_lease_token:source.lease_token||source.leaseToken,p_expected_delivery_version:Number(source.delivery_version??source.deliveryVersion),p_failure_key:`delivery_fail:${source.delivery_id||source.deliveryId}:v${Number(source.delivery_version??source.deliveryVersion)}`,p_error_code:'delivery_send_failed',p_error_text:message.slice(0,2000),p_retry_delay_minutes:1}}}];

