return [{json:{...row,stateEvaluation:row.stateEvaluation||row,stateRpcBody:{p_evaluation_id:row.evaluation_id||row.evaluationId,p_lease_token:row.lease_token||row.leaseToken,p_expected_evaluation_version:Number(row.evaluation_version??row.evaluationVersion),p_completion_key:`evaluation_complete:${row.evaluation_id||row.evaluationId}:${asOfDate}`,p_as_of_date:asOfDate,p_helpfulness_rating:null,p_evaluation_note:null}}}];

