const source=$('Code | Build State Evaluation Complete RPC | Evaluation').item.json||{};
const incoming=$input.first()?.json||{};
const body=incoming.body&&typeof incoming.body==='object'?incoming.body:incoming;
const ok=body?.contractVersion==='chelsea_state_evaluation_complete_v1'&&String(body.evaluationId||'')===String(source.evaluation_id||source.evaluationId||'')&&body.status==='completed';
return [{json:{...source,stateEvaluationResult:body,stateEvaluationCompleted:ok,stateEvaluationError:ok?'':String(body?.message||body?.error?.message||'evaluation_complete_failed')}}];

