      if (questionCodes.has(question?.questionCode)) errors.push(`${prefix}_question_${questionIndex}_duplicate`);
      questionCodes.add(question?.questionCode);
      const optionCodes = new Set();
      for (const [optionIndex, option] of asArray(question?.options).entries()) {
        validateShape(option, ['optionCode','label'], `${prefix}_question_${questionIndex}_option_${optionIndex}`);
        if (!codePattern.test(clean(option?.optionCode)) || !clean(option?.label)) {
          errors.push(`${prefix}_question_${questionIndex}_option_${optionIndex}_invalid`);
        }
        if (optionCodes.has(option?.optionCode)) errors.push(`${prefix}_question_${questionIndex}_option_${optionIndex}_duplicate`);
        optionCodes.add(option?.optionCode);
      }
    }
    if (clarificationPolicy.mode !== 'none' && (!slotCodes.size || !questionCodes.size)) {
      errors.push(`${prefix}_clarification_required_data_empty`);
    }
    if (clarificationPolicy.mode === 'none' && (slotCodes.size || questionCodes.size)) {
      errors.push(`${prefix}_clarification_none_has_data`);
    }
  }
  const financePolicy = rule.financePolicy;
  if (!financePolicy || typeof financePolicy !== 'object' || Array.isArray(financePolicy)) {
    errors.push(`${prefix}_finance_invalid`);
  } else {
    validateShape(financePolicy, ['mode','evidenceRequired','realizedEvidenceRequired','outcomes'], `${prefix}_finance`);
    if (!financeModes.has(financePolicy.mode) || typeof financePolicy.evidenceRequired !== 'boolean' ||
      typeof financePolicy.realizedEvidenceRequired !== 'boolean') {
      errors.push(`${prefix}_finance_policy_invalid`);
    }
    if (!Array.isArray(financePolicy.outcomes)) errors.push(`${prefix}_finance_outcomes_invalid`);
    if (financePolicy.realizedEvidenceRequired && !financePolicy.evidenceRequired) {
      errors.push(`${prefix}_finance_evidence_policy_invalid`);
    }
    const outcomeDirectionPairs = new Set();
    for (const [outcomeIndex, outcome] of asArray(financePolicy.outcomes).entries()) {
      validateShape(outcome, ['outcomeType','directions','evidencePatterns'], `${prefix}_finance_outcome_${outcomeIndex}`);
      if (!codePattern.test(clean(outcome?.outcomeType)) || !Array.isArray(outcome?.directions) ||
        !outcome.directions.length || outcome.directions.some(value => ![-1, 1].includes(value)) ||
        !Array.isArray(outcome?.evidencePatterns) ||
        (financePolicy.realizedEvidenceRequired && !outcome.evidencePatterns.length)) {
        errors.push(`${prefix}_finance_outcome_${outcomeIndex}_invalid`);
      }
      for (const direction of asArray(outcome?.directions)) {
        const pair = `${outcome?.outcomeType}:${direction}`;
        if (outcomeDirectionPairs.has(pair)) errors.push(`${prefix}_finance_outcome_${outcomeIndex}_duplicate`);
        outcomeDirectionPairs.add(pair);
      }
      for (const pattern of asArray(outcome?.evidencePatterns)) {
        try { new RegExp(pattern, 'iu'); } catch { errors.push(`${prefix}_finance_pattern_invalid`); }
      }
    }
    if (financePolicy.mode === 'realized_only' && !asArray(financePolicy.outcomes).length) {
      errors.push(`${prefix}_finance_outcomes_empty`);
    }
  }
  ruleMap.set(ruleCode, rule);
}
if (!ruleMap.size) errors.push('rule_catalog_active_rules_missing');

const result = parsed && typeof parsed === 'object' && !Array.isArray(parsed) ? parsed : {};
validateShape(result, [
  'schemaVersion','ruleSetCode','ruleSetVersion','ruleCatalogVersion',
  'analysisMode','aboutSelf','analysisConfidence',
  'events','userScores','retractions','futurePlans','clarification','neutralFallback'
], 'result');
if (result.schemaVersion !== 'chelsea_state_analysis_v2') errors.push('schema_version_invalid');
if (result.ruleSetCode !== ruleSetCode) errors.push('result_rule_set_code_invalid');
if (result.ruleSetVersion !== ruleSetVersion) errors.push('result_rule_set_version_invalid');
if (result.ruleCatalogVersion !== ruleCatalogVersion) errors.push('result_rule_catalog_version_invalid');
if (!['standard', 'neutral_without_clarification'].includes(result.analysisMode)) {
  errors.push('analysis_mode_invalid');
} else if (result.analysisMode !== expectedAnalysisMode) {
