}
if (typeof result.aboutSelf !== 'boolean') errors.push('about_self_invalid');
if (!inRange(result.analysisConfidence, 0, 1)) errors.push('analysis_confidence_invalid');
for (const field of ['events','userScores','retractions','futurePlans']) {
  if (!Array.isArray(result[field])) errors.push(`${field}_not_array`);
}

let literalEvidenceFallbackCount = 0;
const repairFallbackEvidence = originalSourceText || clarificationAnswerSegments[0] || '';
if (built.stateAnalysisRepairAttempted === true && repairFallbackEvidence) {
  const repairEventCollections = [asArray(result.events), asArray(result.neutralFallback?.events)];
  for (const events of repairEventCollections) {
    for (const event of events) {
      if (event && typeof event === 'object' && !Array.isArray(event) && !exactEvidence(event.evidenceText)) {
        event.evidenceText = repairFallbackEvidence;
        literalEvidenceFallbackCount++;
      }
      if (event && typeof event === 'object' && !Array.isArray(event) && !exactEvidence(event.temporalEvidenceText)) {
        event.temporalEvidenceText = repairFallbackEvidence;
        literalEvidenceFallbackCount++;
      }
    }
  }
  for (const score of asArray(result.userScores)) {
    if (score && typeof score === 'object' && !Array.isArray(score) && !exactEvidence(score.evidenceText)) {
      score.evidenceText = repairFallbackEvidence;
      literalEvidenceFallbackCount++;
    }
    if (score && typeof score === 'object' && !Array.isArray(score) && !exactEvidence(score.temporalEvidenceText)) {
      score.temporalEvidenceText = repairFallbackEvidence;
      literalEvidenceFallbackCount++;
    }
  }
  for (const plans of [asArray(result.futurePlans), asArray(result.neutralFallback?.futurePlans)]) {
    for (const plan of plans) {
      if (plan && typeof plan === 'object' && !Array.isArray(plan) && !exactEvidence(plan.evidenceText)) {
        plan.evidenceText = repairFallbackEvidence;
        literalEvidenceFallbackCount++;
      }
      if (plan && typeof plan === 'object' && !Array.isArray(plan) && !exactEvidence(plan.temporalEvidenceText)) {
        plan.temporalEvidenceText = repairFallbackEvidence;
        literalEvidenceFallbackCount++;
      }
    }
  }
}

const activeEffects = new Map();
const activeEvents = new Map();
const effectSources = context.recentActiveEffects || context.recent_active_effects || context.recentEffects || context.recent_effects || context.effects;
for (const effect of asArray(effectSources)) {
  const id = clean(effect.effectId || effect.effect_id || effect.id);
  if (id) {
    activeEffects.set(id, {
      version: Number(effect.version),
      sphereCode: clean(effect.sphereCode || effect.sphere_code),
      status: clean(effect.status || 'active'),
      ruleCode: clean(effect.ruleCode || effect.rule_code),
      ruleSetVersion: clean(effect.ruleSetVersion || effect.rule_set_version)
    });
  }
  const eventId = clean(effect.eventId || effect.event_id);
  if (eventId && Number.isSafeInteger(Number(effect.eventVersion ?? effect.event_version))) {
    activeEvents.set(eventId, {
      version: Number(effect.eventVersion ?? effect.event_version),
      status: clean(effect.eventStatus || effect.event_status || 'active'),
      ruleCode: clean(effect.ruleCode || effect.rule_code),
      ruleSetVersion: clean(effect.ruleSetVersion || effect.rule_set_version)
    });
  }
}
for (const event of asArray(context.recentActiveEvents || context.recent_active_events || context.activeEvents || context.active_events)) {
  const id = clean(event.eventId || event.event_id || event.id);
  if (!id) continue;
  activeEvents.set(id, {
    version: Number(event.version),
    status: clean(event.status || 'active'),
    ruleCode: clean(event.ruleCode || event.rule_code),
    ruleSetVersion: clean(event.ruleSetVersion || event.rule_set_version)
  });
}
if (eventCorrection) {
  const targetEventId = clean(eventCorrection.targetEventId || correctionTarget.eventId || correctionTarget.id);
  const targetVersion = Number(eventCorrection.expectedTargetVersion ?? correctionTarget.version);
  if (targetEventId) {
    activeEvents.set(targetEventId, {
      version: targetVersion,
      status: clean(correctionTarget.status || 'active'),
      ruleCode: clean(correctionTarget.ruleCode || correctionTarget.rule_code),
      ruleSetVersion: clean(correctionTarget.ruleSetVersion || correctionTarget.rule_set_version)
    });
  }
  for (const effect of asArray(eventCorrection.targetActiveEffects || correctionTarget.activeEffects)) {
    const effectId = clean(effect?.effectId || effect?.effect_id || effect?.id);
    if (!effectId) continue;
    activeEffects.set(effectId, {
      version: Number(effect.version),
      sphereCode: clean(effect.sphereCode || effect.sphere_code),
      status: clean(effect.status || 'active'),
      ruleCode: clean(correctionTarget.ruleCode || correctionTarget.rule_code),
      ruleSetVersion: clean(correctionTarget.ruleSetVersion || correctionTarget.rule_set_version)
    });
  }
}
const activeUserScores = new Map();
for (const score of asArray(context.recentActiveUserScores || context.recent_active_user_scores || context.recentUserScores || context.userScores)) {
  const id = clean(score.userScoreId || score.user_score_id || score.id);
  if (!id) continue;
  activeUserScores.set(id, {
    version: Number(score.version),
    sphereCode: clean(score.sphereCode || score.sphere_code),
    status: clean(score.status || 'active')
  });
